svg.script:
(async function () {

  const frame = document.getElementById("gameFrame");

  const htmlURL =
    "https://raw.githubusercontent.com/atharvchoudhari123/Sites/refs/heads/main/games/sources/AlienHonmind.html";

  try {
    const response = await fetch(htmlURL, {
      cache: "no-cache"
    });

    if (!response.ok) {
      throw new Error(
        "HTTP " + response.status + " while loading game HTML"
      );
    }

    const html = await response.text();

    frame.srcdoc = html;

  } catch (error) {

    console.error("Failed to load Alien Hominid:", error);

    frame.srcdoc = `
      <!DOCTYPE html>
      <html>
      <body style="
        margin:0;
        background:black;
        color:white;
        font-family:Arial,sans-serif;
        display:flex;
        align-items:center;
        justify-content:center;
        height:100vh;
      ">
        <div style="text-align:center">
          <h2>Failed to load Alien Hominid</h2>
          <p>${String(error).replace(/</g, "&lt;")}</p>
        </div>
      </body>
      </html>
    `;
  }

})();
